import {useEffect,useRef,useState} from 'react';import ReactMarkdown from 'react-markdown';import remarkGfm from 'remark-gfm';import {LayoutDashboard,ArrowLeftRight,Settings,Plus,Upload,ChevronRight,ChevronDown,AlertCircle,Search,X,Check,RotateCcw,Database,WalletCards,TrendingUp,PiggyBank,Landmark,FileText,Trash2,Menu,SquarePen,Send,MessageSquare,HardDrive,UserRound,LogOut,Minus,Square,PanelLeftClose,PanelLeftOpen,Image,ShieldCheck,KeyRound,Leaf,CalendarDays,Gauge,Target,ChevronLeft,ArrowRight,Copy,ThumbsUp,ThumbsDown,Share2,RefreshCw,MoreHorizontal,Mic} from 'lucide-react';import './App.css';
