 useEffect(()=>{localStorage.setItem('jerri.shell.sidebar.collapsed.v2',String(sidebarCollapsed))},[sidebarCollapsed]);
 useEffect(()=>{localStorage.setItem('jerri.workspace.tabs.v1',JSON.stringify(tabs));localStorage.setItem('jerri.workspace.active.v1',activeTab.id)},[tabs,activeTab.id]);
 const names:Record<View,string>={dashboard:'Dashboard',transactions:'Transactions',insights:'Insights',ask:'Ask Jerri',goals:'Goals',settings:'Settings'};
