 const openDocument=(document:any)=>{const documentId=document?.documentId||document?.id||document?.fileHash;if(!documentId){setError('This file does not have a stored document copy yet. Choose or import it again.');return}const id=`document:${documentId}`,title=document.name||document.fileName||'Document';setTabs(items=>items.some(tab=>tab.id===id)?items:[...items,{id,kind:'document',documentId,title}]);setActiveTabId(id)};
 const closeTab=(id:string)=>{if(id===defaultTab.id)return;setTabs(items=>{const index=items.findIndex(tab=>tab.id===id),remaining=items.filter(tab=>tab.id!==id);if(id===activeTab.id)setActiveTabId((remaining[Math.max(0,index-1)]||remaining[0]||defaultTab).id);return remaining.length?remaining:[defaultTab]})};
 const load=async()=>{try{setBusy(true);const b=await window.finance.bootstrap();setBoot(b);setDash(b.dashboard);setInsight(b.insights);setGoals(b.goals||[]);setFilters(f=>({...f,month:b.dashboard.month}))}catch(e:any){setError(userError(e,'Could not open your finance workspace.'))}finally{setBusy(false)}};useEffect(()=>{void load()},[]);
 const notify=(m:string)=>{setToast(m);setTimeout(()=>setToast(''),3500)};const addFiles=async()=>{try{setError('');const p=await window.finance.chooseImportFiles();if(p){setPreview(p);setPreviewOpen(true)}}catch(e:any){setError(userError(e))}};
 const confirmImport=async()=>{try{setBusy(true);const b=await window.finance.confirmImport(preview.id);setBoot(b);setDash(b.dashboard);setFilters(f=>({...f,month:b.dashboard.month}));setPreview(null);setPreviewOpen(false);openView('dashboard');notify('Files imported and dashboard updated.')}catch(e:any){setError(userError(e))}finally{setBusy(false)}};
 const openTransactions=async(extra?:any)=>{try{setError('');openView('transactions');const f=extra?{search:'',month:extra.month||dash?.month||filters.month,...extra}:filters;setFilters(f);setTransactions(await window.finance.transactions(f))}catch(e:any){setError(userError(e,'Could not load transactions.'))}};
