 const selectMonth=async(m:string)=>{try{setError('');setDash(await window.finance.dashboard(m));setInsight(await window.finance.insights(m));setFilters(f=>({...f,month:m==='all'?'':m}))}catch(e:any){setError(userError(e,'Could not load that month.'))}};
 if(busy&&!boot)return <div className="loading"><p>Preparing your finance workspace…</p></div>;
