function TitleBar({tabs,activeId,selectTab,closeTab,openTransactions}:any){const [maximized,setMaximized]=useState(false);useEffect(()=>{window.finance.windowControl('state').then(setMaximized).catch(()=>{})},[]);const control=async(action:'minimize'|'toggle-maximize'|'close')=>{const state=await window.finance.windowControl(action);if(action==='toggle-maximize')setMaximized(state)};const search=()=>{openTransactions();setTimeout(()=>document.querySelector<HTMLInputElement>('.transactions .search input')?.focus(),0)};return <div className="titlebar"><div className="titlebar-tabs">{tabs.map((tab:any)=><div className={`titlebar-tab ${tab.id===activeId?'active':''}`} key={tab.id}><button onClick={()=>selectTab(tab.id)}>{tab.kind==='document'&&<FileText size={13}/>}<span>{tab.title}</span></button>{tab.id!=='view:dashboard'&&<button className="titlebar-tab-close" aria-label={`Close ${tab.title} tab`} onClick={()=>closeTab(tab.id)}><X size={13}/></button>}</div>)}</div><div className="titlebar-drag"/><button className="titlebar-search" onClick={search}><Search size={14}/><span>Search</span></button><div className="window-controls"><button aria-label="Minimize window" onClick={()=>void control('minimize')}><Minus size={15}/></button><button aria-label={maximized?'Restore window':'Maximize window'} onClick={()=>void control('toggle-maximize')}>{maximized?<span className="restore-icon"/>:<Square size={12}/>}</button><button className="window-close" aria-label="Close window" onClick={()=>void control('close')}><X size={15}/></button></div></div>}

const parseDelimited=(text:string,delimiter:string)=>{const rows:string[][]=[];let row:string[]=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const char=text[i];if(char==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(char===delimiter&&!quoted){row.push(cell);cell=''}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(value=>value.length))rows.push(row);row=[];cell=''}else cell+=char}row.push(cell);if(row.some(value=>value.length))rows.push(row);return rows};
function DocumentView({documentId,title}:any){const [document,setDocument]=useState<any>(),[error,setError]=useState(''),[blobUrl,setBlobUrl]=useState('');useEffect(()=>{let disposed=false,url='';setDocument(undefined);setError('');window.finance.documentRead(documentId).then(result=>{if(disposed)return;const bytes=result.data instanceof Uint8Array?result.data:new Uint8Array(result.data),metadata=result.metadata,text=metadata.kind==='text'||metadata.kind==='table'?new TextDecoder().decode(bytes):'';if(metadata.kind==='pdf'||metadata.kind==='image'){url=URL.createObjectURL(new Blob([bytes],{type:metadata.mime}));setBlobUrl(url)}else setBlobUrl('');setDocument({...metadata,text})}).catch(e=>!disposed&&setError(userError(e,'Could not open this document.')));return()=>{disposed=true;if(url)URL.revokeObjectURL(url)}},[documentId]);if(error)return <section className="document-page"><div className="document-error"><AlertCircle/><h2>Document unavailable</h2><p>{error}</p><button className="primary" onClick={async()=>{try{const recovered=await window.finance.documentRecover({id:documentId,name:title});if(recovered)window.location.reload()}catch(e:any){setError(userError(e,'Could not recover this document.'))}}}>Locate original file</button></div></section>;if(!document)return <section className="document-page"><div className="document-loading">Opening {title}…</div></section>;let content;if(document.kind==='pdf')content=<iframe className="document-pdf" src={blobUrl} title={document.name}/>;else if(document.kind==='image')content=<div className="document-image"><img src={blobUrl} alt={document.name}/></div>;else if(document.kind==='table'){const rows=parseDelimited(document.text,document.mime==='text/tab-separated-values'?'\t':','),shown=rows.slice(0,2001);content=<div className="document-table-wrap"><table className="document-table"><thead><tr>{(shown[0]||[]).map((cell:string,index:number)=><th key={index}>{cell||`Column ${index+1}`}</th>)}</tr></thead><tbody>{shown.slice(1).map((row:string[],rowIndex:number)=><tr key={rowIndex}>{row.map((cell:string,index:number)=><td key={index}>{cell}</td>)}</tr>)}</tbody></table>{rows.length>2001&&<p className="document-limit">Showing the first 2,000 rows of {rows.length-1}.</p>}</div>}else if(document.mime==='text/markdown')content=<div className="document-text markdown-document"><ReactMarkdown remarkPlugins={[remarkGfm]}>{document.text}</ReactMarkdown></div>;else{let text=document.text;if(document.mime==='application/json')try{text=JSON.stringify(JSON.parse(text),null,2)}catch{}content=<pre className="document-text">{text}</pre>}return <section className="document-page"><div className="document-toolbar"><div><FileText size={18}/><span><b>{document.name}</b><small>{document.mime} · {(document.size/1048576).toFixed(document.size>1048576?1:2)} MB</small></span></div><span>Stored safely in Jerri Finance</span></div><div className="document-canvas">{content}</div></section>}

