 const connect=async()=>{try{setWorking(true);setError('');apply(await window.finance.aiSetup({providerId,modelId:selected,reasoningEffort:reasoning,contextScope,apiKey:providerId==='anthropic'?apiKey:undefined}));setApiKey('');setSetupOpen(false)}catch(e:any){setError(userError(e,'Could not connect this provider.'))}finally{setWorking(false)}};
