 const quickReasoning=async(value:string)=>{try{setReasoning(value);apply(await window.finance.aiConfigure({providerId,modelId:selected,reasoningEffort:value,contextScope}));setQuickOpen(false)}catch(e:any){setError(userError(e))}};
